def compare_versions(a: str, b: str) -> int:
    def parse(version: str) -> list[str]:
        if not isinstance(version, str):
            raise ValueError("version must be a string")

        parts = version.split(".")
        if any(not part or not part.isascii() or not part.isdecimal() for part in parts):
            raise ValueError("version parts must contain only decimal digits")

        normalized = []
        for part in parts:
            value = part.lstrip("0")
            normalized.append(value or "0")
        return normalized

    parts_a = parse(a)
    parts_b = parse(b)

    length = max(len(parts_a), len(parts_b))
    for index in range(length):
        part_a = parts_a[index] if index < len(parts_a) else "0"
        part_b = parts_b[index] if index < len(parts_b) else "0"

        if len(part_a) < len(part_b):
            return -1
        if len(part_a) > len(part_b):
            return 1
        if part_a < part_b:
            return -1
        if part_a > part_b:
            return 1

    return 0
```

